import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, positionLocal, normalLocal, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    SphereGeometry,
    Color,
    Vector3,
    SRGBColorSpace
  } = THREE;

  const root = new Group();
  root.name = config.id || 'features-ornamental-divider';
  root.userData.handlers = {};

  const timelines = new Set();
  const geometries = new Set();
  const materials = new Set();
  const textures = new Set();
  let disposed = false;

  const colors = config.intent?.visualSpec?.colors || {};
  const ink = colors.ink || '#16161d';
  const paper = colors.paper || '#e8ecf2';
  const accent = colors.accent || '#ff2a38';
  const surface = colors.surface || '#0b0b10';

  const trackTimeline = (timeline) => {
    if (timeline) timelines.add(timeline);
    return timeline;
  };

  const registerGeometry = (geometry) => {
    geometries.add(geometry);
    return geometry;
  };

  const registerMaterial = (material) => {
    materials.add(material);
    return material;
  };

  const registerTexture = (tex) => {
    if (tex) textures.add(tex);
    return tex;
  };

  const makeStandardMaterial = (color, metalness = 0.35, roughness = 0.58) => {
    const material = registerMaterial(new MeshStandardNodeMaterial());
    material.color = new Color(color);
    material.metalness = metalness;
    material.roughness = roughness;
    return material;
  };

  const stageGeometry = registerGeometry(new PlaneGeometry(4.8, 0.9, 64, 16));
  const stageMaterial = registerMaterial(new MeshBasicNodeMaterial());
  stageMaterial.color = new Color(surface);
  stageMaterial.transparent = true;
  stageMaterial.opacity = 0.96;

  const stage = new Mesh(stageGeometry, stageMaterial);
  stage.name = 'machined-divider-stage';
  stage.position.z = -0.16;
  root.add(stage);

  const edgeGeometry = registerGeometry(new BoxGeometry(4.65, 0.018, 0.025));
  const edgeMaterial = makeStandardMaterial(ink, 0.48, 0.56);
  const upperEdge = new Mesh(edgeGeometry, edgeMaterial);
  upperEdge.position.set(0, 0.22, -0.02);
  root.add(upperEdge);

  const lowerEdge = new Mesh(
    registerGeometry(new BoxGeometry(4.65, 0.012, 0.025)),
    makeStandardMaterial(paper, 0.42, 0.62)
  );
  lowerEdge.position.set(0, -0.22, -0.018);
  lowerEdge.scale.x = 0.72;
  root.add(lowerEdge);

  const ruleGeometry = registerGeometry(new BoxGeometry(4.05, 0.025, 0.045));
  const ruleMaterial = makeStandardMaterial(paper, 0.5, 0.52);
  const rule = new Mesh(ruleGeometry, ruleMaterial);
  rule.name = 'machined-rule';
  rule.position.z = 0.035;
  root.add(rule);

  const insetGeometry = registerGeometry(new BoxGeometry(3.85, 0.008, 0.012));
  const insetMaterial = makeStandardMaterial(ink, 0.45, 0.6);
  const inset = new Mesh(insetGeometry, insetMaterial);
  inset.position.set(0, -0.026, 0.06);
  root.add(inset);

  const jewelGeometry = registerGeometry(new SphereGeometry(0.105, 24, 16));
  const jewelMaterial = registerMaterial(new MeshStandardNodeMaterial());
  jewelMaterial.color = new Color(accent);
  jewelMaterial.emissive = new Color(accent);
  jewelMaterial.emissiveIntensity = 1.35;
  jewelMaterial.metalness = 0.28;
  jewelMaterial.roughness = 0.3;

  const jewel = new Mesh(jewelGeometry, jewelMaterial);
  jewel.name = 'center-signal-jewel';
  jewel.position.set(0, 0, 0.16);
  root.add(jewel);

  const jewelMount = new Mesh(
    registerGeometry(new SphereGeometry(0.145, 20, 12)),
    makeStandardMaterial(ink, 0.52, 0.5)
  );
  jewelMount.scale.z = 0.42;
  jewelMount.position.set(0, 0, 0.095);
  root.add(jewelMount);

  const focusGeometry = registerGeometry(new BoxGeometry(4.68, 0.032, 0.012));
  const focusMaterial = registerMaterial(new MeshBasicNodeMaterial());
  focusMaterial.color = new Color(accent);
  focusMaterial.transparent = true;
  focusMaterial.opacity = 0;

  const focusEdge = new Mesh(focusGeometry, focusMaterial);
  focusEdge.name = 'focus-accent-edge';
  focusEdge.position.set(0, 0.255, 0.08);
  root.add(focusEdge);

  const imageUrl = config.imageUrl;
  const depthMapUrl = config.depthMapUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (disposed || !tex) return;
      registerTexture(tex);
      tex.colorSpace = SRGBColorSpace || tex.colorSpace;

      const imageMaterial = registerMaterial(new MeshBasicNodeMaterial());
      imageMaterial.transparent = true;
      imageMaterial.opacity = 0.22;
      imageMaterial.colorNode = texture(tex);

      const imagePlane = new Mesh(
        registerGeometry(new PlaneGeometry(4.45, 0.72, 64, 32)),
        imageMaterial
      );
      imagePlane.name = 'parallax-image-plane';
      imagePlane.position.set(0, 0, -0.075);
      root.add(imagePlane);

      if (depthMapUrl) {
        ctx.textureLoader.loadTexture(depthMapUrl).then((depthTex) => {
          if (disposed || !depthTex) return;
          registerTexture(depthTex);

          imageMaterial.positionNode = positionLocal.add(
            normalLocal.mul(texture(depthTex).r.sub(float(0.5)).mul(float(0.055)))
          );
          imageMaterial.needsUpdate = true;
        }).catch(() => {});
      }
    }).catch(() => {});
  }

  const hoverLift = (active = true) => {
    if (disposed) return;
    const targetY = active ? -0.15 : 0;
    const timeline = gsap.timeline({
      onComplete: () => timelines.delete(timeline)
    });
    trackTimeline(timeline);
    timeline.to(root.position, {
      y: targetY,
      duration: active ? 0.42 : 0.34,
      ease: 'power3.out'
    });
    timeline.to(root.rotation, {
      x: active ? -0.018 : 0,
      duration: 0.3,
      ease: 'power2.out'
    }, 0);
  };

  root.userData.handlers.hover = (active = true) => {
    if (typeof active === 'object') {
      active = active.active ?? active.hovered ?? true;
    }
    hoverLift(active !== false);
  };

  root.userData.handlers.click = () => {
    if (disposed) return;

    const press = gsap.timeline({
      onComplete: () => timelines.delete(press)
    });
    trackTimeline(press);
    press.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power2.out'
    });
    press.to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.36,
      ease: 'back.out(3)'
    });

    ctx.emit('hub-features.select', {
      nodeId: config.id || 'features-ornamental-divider'
    });
  };

  root.userData.handlers.focus = (active = true) => {
    if (typeof active === 'object') {
      active = active.active ?? active.focused ?? true;
    }

    const focus = gsap.timeline({
      onComplete: () => timelines.delete(focus)
    });
    trackTimeline(focus);
    focus.to(focusMaterial, {
      opacity: active ? 0.95 : 0,
      duration: 0.2,
      ease: 'power2.out'
    });
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    timelines.forEach((timeline) => timeline.kill());
    timelines.clear();

    root.traverse((object) => {
      if (object.geometry) geometries.add(object.geometry);
      if (object.material) {
        const list = Array.isArray(object.material)
          ? object.material
          : [object.material];
        list.forEach((material) => materials.add(material));
      }
    });

    geometries.forEach((geometry) => geometry.dispose());
    materials.forEach((material) => material.dispose());
    textures.forEach((tex) => tex.dispose());

    root.clear();
  };

  return root;
}
